// ORDERS: [{ week: 'W1', North: 1480, East: 920, West: 1310 }, \u2026]
// REGIONS: [{ key: 'North', color: 'cyan.6' }, { key: 'East', color: 'orange.6' }, { key: 'West', color: 'purple.6' }]

